def create_vector_extension(apps, schema_editor):
    """Create the pgvector extension on Postgres; no-op elsewhere.

    SQLite-based system checks and any non-Postgres dev database must not
    explode on this migration, so the raw SQL only runs on PostgreSQL.
    (Equivalent to pgvector.django.VectorExtension, vendor-guarded.)
    """
